import{_ as a}from"./chunks/connect.BTLErx-Y.js";import{_ as t,o as n,c as i,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const g=JSON.parse('{"title":"Connecting and signing in","description":"","frontmatter":{"pageId":"players/connect","contentRevision":1},"headers":[],"relativePath":"en/players/connect.md","filePath":"en/players/connect.md"}'),r={name:"en/players/connect.md"};function s(c,e,l,d,h,p){return n(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="connecting-and-signing-in" tabindex="-1">Connecting and signing in <a class="header-anchor" href="#connecting-and-signing-in" aria-label="Permalink to &quot;Connecting and signing in&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><img class="wiki-art" src="'+a+'" alt="Two colonies connect to the server over a secure connection." width="960" height="440"><p class="wiki-caption">Two colonies connect to the server over a secure connection.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Add the host and port in <strong>Multiplayer</strong> (default 25560). Obtain the address from the administrator; the browser panel URL and game endpoint need not match. A server-wide password, if configured, is additional to personal authentication.</p><p>Steam login uses a Steam ticket. Password login is available only when enabled by the server; credentials belong to that server. A new certificate is remembered after trust is granted. If its pin changes, confirm the certificate replacement with the administrator first.</p><p>After login the server loads your saved colony, offers a new colony, or shows modpack differences. Resolve the listed differences and reconnect.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Do not disable TLS to work around certificate errors. Never send personal passwords in chat. For a temporary Steam refusal, let authentication retry rather than creating many accounts.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./modpacks">Server modpacks</a></li><li><a href="./../admins/security-auth">TLS, authentication and permissions</a></li><li><a href="./troubleshooting">Player troubleshooting</a></li></ul>',12)])])}const u=t(r,[["render",s]]);export{g as __pageData,u as default};
